// the first address of X-Forwarded-For when the proxy in front of the service
// set one, otherwise the host of the peer address. A header value that names
// no address falls back to the peer, so a client cannot share another's
// counter by writing the header itself.
func clientIP(r *http.Request) string {
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
