// TestLimiterCountsAttemptsTogether is the counter under concurrent requests:
// one window of one key shared by many goroutines holds exactly its limit of
// attempts, no more and no fewer, so two logins at once cannot both slip past
// the tenth.
func TestLimiterCountsAttemptsTogether(t *testing.T) {
	l := newLimiter(AuthMaxAttempts, authWindow)
	var wg sync.WaitGroup
	var allowed atomic.Int64
	for range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 10 {
				if l.allow("203.0.113.7") {
					allowed.Add(1)
				}
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != AuthMaxAttempts {
		t.Errorf("%d attempts allowed from one address in one window, want the limit of %d",
			got, AuthMaxAttempts)
	}
}

